code.perFrame:
n=0;
zbuf=1;
zbclear=1;

/*
 global per frame
*/

bf1=1+dbf1;
dbf1=dbf1*pow(.15,dt);
dry=dry*pow(.65,dt)+.015;

// temp test rotations and lights
rx=.2*cos(.57*rz+.8);rz=rz+.8*dry*dt;ry=.1*sin(.4*rz);
ox=175*sin(-rz);oy=175*cos(-rz);oz=350-100*cos(.3*t);
orx=$PI;ory=.4*cos(.5*t);orz=-.5*(rz+$PI+.8*sin(1.2*rz));

l1x=100;l1y=0;l1z=-250;
l2x=-100;l2y=0;l2z=-250;
l3x=300;l3y=0;l3z=0;
l4x=-300;l4y=0;l4z=0;
l5x=0;l5y=0;l5z=150;

l1r=12500*bf1;l1g=12500*bf1;l1b=20000*bf1;
l2r=12500*bf1;l2g=12500*bf1;l2b=20000*bf1;
l3r=20000*sin($PI*t);l3g=5000*sin($PI*t);l3b=5000*sin($PI*t);
l4r=-5000*sin($PI*t);l4g=-20000*sin($PI*t);l4b=-5000*sin($PI*t);
l5r=5000;l5g=5000;l5b=5000;
l3r=max(l3r,0);l3g=max(l3g,0);l3b=max(l3b,0);
l4r=max(l4r,0);l4g=max(l4g,0);l4b=max(l4b,0);

// texer offset here for easy tweaking should it prove useful
toff=66;

// set up time, fps and aspect ratio junk
t=gettime(0);
reg00=0;
reg01=0;
reg02=t;
dt=gettime(lasttime);lasttime=gettime(0);
reg03=dt;
reg04=w/h;
reg05=h/w;
fpc=(fpc+1)%5;
reg50=if(fpc,reg50,1/dt);
reg51=w;reg52=h;

reg10=rx;reg11=ry;reg12=rz;
reg13=ox;reg14=oy;reg95=oz;
reg15=orx;reg16=ory;reg17=orz;

reg18=l1x;reg19=l1y;reg20=l1z;
reg21=l2x;reg22=l2y;reg23=l2z;
reg24=l3x;reg25=l3y;reg26=l3z;
reg27=l4x;reg28=l4y;reg29=l4z;
reg42=l5x;reg43=l5y;reg44=l5z;

reg30=l1r;reg31=l1g;reg32=l1b;
reg33=l2r;reg34=l2g;reg35=l2b;
reg36=l3r;reg37=l3g;reg38=l3b;
reg39=l4r;reg40=l4g;reg41=l4b;
reg45=l5r;reg46=l5g;reg47=l5b;


// rotation of ship
srx=-sin(rx);crx=cos(rx);
sry=-sin(ry);cry=cos(ry);
srz=-sin(rz);crz=cos(rz);

cxx=1;cxy=0;cxz=0;     // x component vector
cyx=0;cyy=1;cyz=0;     // y component vector
czx=0;czy=0;czz=1;     // z component vector

// rotate all three components
tz=cxz*cry-cxx*sry; 
tx=cxz*sry+cxx*cry;
ty=cxy*crx-tz*srx;
cxz=cxy*srx+tz*crx;
cxx=tx*crz-ty*srz;
cxy=tx*srz+ty*crz;

tz=cyz*cry-cyx*sry; 
tx=cyz*sry+cyx*cry;
ty=cyy*crx-tz*srx;
cyz=cyy*srx+tz*crx;
cyx=tx*crz-ty*srz;
cyy=tx*srz+ty*crz;

tz=czz*cry-czx*sry; 
tx=czz*sry+czx*cry;
ty=czy*crx-tz*srx;
czz=czy*srx+tz*crx;
czx=tx*crz-ty*srz;
czy=tx*srz+ty*crz;

reg60=cxx;reg61=cxy;reg62=cxz;
reg63=cyx;reg64=cyy;reg65=cyz;
reg66=czx;reg67=czy;reg68=czz;

// rotation of camera (ssc)
srx=-sin(orx);crx=cos(orx);
sry=-sin(ory);cry=cos(ory);
srz=-sin(orz);crz=cos(orz);

cxx=1;cxy=0;cxz=0;     // x component vector
cyx=0;cyy=1;cyz=0;     // y component vector
czx=0;czy=0;czz=1;     // z component vector

// rotate all three components
tz=cxz*cry-cxx*sry; 
tx=cxz*sry+cxx*cry;
ty=cxy*crx-tz*srx;
cxz=cxy*srx+tz*crx;
cxx=tx*crz-ty*srz;
cxy=tx*srz+ty*crz;

tz=cyz*cry-cyx*sry; 
tx=cyz*sry+cyx*cry;
ty=cyy*crx-tz*srx;
cyz=cyy*srx+tz*crx;
cyx=tx*crz-ty*srz;
cyy=tx*srz+ty*crz;

tz=czz*cry-czx*sry; 
tx=czz*sry+czx*cry;
ty=czy*crx-tz*srx;
czz=czy*srx+tz*crx;
czx=tx*crz-ty*srz;
czy=tx*srz+ty*crz;

reg70=cxx;reg71=cxy;reg72=cxz;
reg73=cyx;reg74=cyy;reg75=cyz;
reg76=czx;reg77=czy;reg78=czz;

// rotation of camera (dm)
srx=sin(orx);crx=cos(orx);
sry=sin(ory);cry=cos(ory);
srz=sin(orz);crz=cos(orz);

cxx=1;cxy=0;cxz=0;     // x component vector
cyx=0;cyy=1;cyz=0;     // y component vector
czx=0;czy=0;czz=1;     // z component vector

// rotate all three components
tx=cxx*crz-cxy*srz;
ty=cxx*srz+cxy*crz;
cxy=ty*crx-cxz*srx;
tz=ty*srx+cxz*crx;
cxz=tz*cry-tx*sry; 
cxx=tz*sry+tx*cry;

tx=cyx*crz-cyy*srz;
ty=cyx*srz+cyy*crz;
cyy=ty*crx-cyz*srx;
tz=ty*srx+cyz*crx;
cyz=tz*cry-tx*sry; 
cyx=tz*sry+tx*cry;

tx=czx*crz-czy*srz;
ty=czx*srz+czy*crz;
czy=ty*crx-czz*srx;
tz=ty*srx+czz*crx;
czz=tz*cry-tx*sry; 
czx=tz*sry+tx*cry;

reg80=cxx;reg81=cxy;reg82=cxz;
reg83=cyx;reg84=cyy;reg85=cyz;
reg86=czx;reg87=czy;reg88=czz;

// transform the two texer centers

tx1=toff;ty1=0;tz1=0;
tx2=-toff;ty1=0;tz1=0;

tx=tx1*reg60+ty1*reg63+tz1*reg66 - ox;
ty=tx1*reg61+ty1*reg64+tz1*reg67 - oy;
tz=tx1*reg62+ty1*reg65+tz1*reg68 - oz;
tx1=tx*reg70+ty*reg73+tz*reg76;
ty1=tx*reg71+ty*reg74+tz*reg77;
tz1=tx*reg72+ty*reg75+tz*reg78;

tx=tx2*reg60+ty2*reg63+tz2*reg66 - ox;
ty=tx2*reg61+ty2*reg64+tz2*reg67 - oy;
tz=tx2*reg62+ty2*reg65+tz2*reg68 - oz;
tx2=tx*reg70+ty*reg73+tz*reg76;
ty2=tx*reg71+ty*reg74+tz*reg77;
tz2=tx*reg72+ty*reg75+tz*reg78;

// work out distances to camera

td1=sqrt(sqr(tx1)+sqr(ty1)+sqr(tz1));
td2=sqrt(sqr(tx2)+sqr(ty2)+sqr(tz2));

reg90=td1;reg91=td2;

/*
 dm per frame
*/

// time, aspect ratio etc
time=reg02;
asp=if(above(h,w),reg04,reg05);

// camera position
ox=reg13;oy=reg14;oz=reg95;

// world rotation (camera rotation)
wcxx=reg80;wcxy=reg81;wcxz=reg82;
wcyx=reg83;wcyy=reg84;wcyz=reg85;
wczx=reg86;wczy=reg87;wczz=reg88;

// initialise counter
c=0;

code.perPoint:
