tmpx=x1*t+ox;tmpy=y1*t+oy;tmpz=z1*t+oz;
t=t-(sqr(sqr(tmpx))+sqr(sqr(.6*tmpy))-blobm)*wh;

wh=.000000001;
tmpx=x1*t+ox;tmpy=y1*t+oy;tmpz=z1*t+oz;
t=t-(sqr(sqr(tmpx))+sqr(sqr(.6*tmpy))-blobm)*wh;
tmpx=x1*t+ox;tmpy=y1*t+oy;tmpz=z1*t+oz;
t=t-(sqr(sqr(tmpx))+sqr(sqr(.6*tmpy))-blobm)*wh;
tmpx=x1*t+ox;tmpy=y1*t+oy;tmpz=z1*t+oz;
t=t-(sqr(sqr(tmpx))+sqr(sqr(.6*tmpy))-blobm)*wh;

wh=.000000004;
tmpx=x1*t+ox;tmpy=y1*t+oy;tmpz=z1*t+oz;
t=t-(sqr(sqr(tmpx))+sqr(sqr(.6*tmpy))-blobm)*wh;
tmpx=x1*t+ox;tmpy=y1*t+oy;tmpz=z1*t+oz;
t=t-(sqr(sqr(tmpx))+sqr(sqr(.6*tmpy))-blobm)*wh;
tmpx=x1*t+ox;tmpy=y1*t+oy;tmpz=z1*t+oz;
t=t-(sqr(sqr(tmpx))+sqr(sqr(.6*tmpy))-blobm)*wh;

wh=.000000001;
tmpx=x1*t+ox;tmpy=y1*t+oy;tmpz=z1*t+oz;
t=t-(sqr(sqr(tmpx))+sqr(sqr(.6*tmpy))-blobm)*wh;
tmpx=x1*t+ox;tmpy=y1*t+oy;tmpz=z1*t+oz;
t=t-(sqr(sqr(tmpx))+sqr(sqr(.6*tmpy))-blobm)*wh;
tmpx=x1*t+ox;tmpy=y1*t+oy;tmpz=z1*t+oz;
t=t-(sqr(sqr(tmpx))+sqr(sqr(.6*tmpy))-blobm)*wh;

d=sqr(x1*t)+sqr(y1*t)+sqr(z1*t);
x1=x1*t+ox;
y1=y1*t+oy;
z1=z1*t+oz;

x=.125*$PI*abs(atan2(x1,y1))-.4;
y=-.5-.0002*z1;
alpha=(2.3-.00000035*d)*.35;

