code.perFrame:
/*
 triangle per frame
*/

// offset to use in gmegabuf
offset=0;
n=gmegabuf(offset);

// material settings
mdr=.5;mdg=.5;mdb=.5;
mgr=2;mgg=2;mgb=2;
mar=.25;mag=.25;mab=.25;
msp=4;

// zbuffer stuff
zbuf=1;

// time, aspect ratio etc
t=reg02;
asp=if(above(h,w),reg04,reg05);
reg01=reg01+n;


// camera position
ox=reg13;oy=reg14;oz=reg95;

// light positions
l1x=reg18;l1y=reg19;l1z=reg20;
l2x=reg21;l2y=reg22;l2z=reg23;
l3x=reg24;l3y=reg25;l3z=reg26;
l4x=reg27;l4y=reg28;l4z=reg29;
l5x=reg42;l5y=reg43;l5z=reg44;

// light colors
l1r=reg30;l1g=reg31;l1b=reg32;
l2r=reg33;l2g=reg34;l2b=reg35;
l3r=reg36;l3g=reg37;l3b=reg38;
l4r=reg39;l4g=reg40;l4b=reg41;
l5r=reg45;l5g=reg46;l5b=reg47;

// model rotation
mcxx=reg60;mcxy=reg61;mcxz=reg62;
mcyx=reg63;mcyy=reg64;mcyz=reg65;
mczx=reg66;mczy=reg67;mczz=reg68;

// world rotation (camera rotation)
wcxx=reg70;wcxy=reg71;wcxz=reg72;
wcyx=reg73;wcyy=reg74;wcyz=reg75;
wczx=reg76;wczy=reg77;wczz=reg78;


// transform light positions
tx1=l1x;ty1=l1y;tz1=l1z;
tx=tx1*reg60+ty1*reg63+tz1*reg66 - ox;
ty=tx1*reg61+ty1*reg64+tz1*reg67 - oy;
tz=tx1*reg62+ty1*reg65+tz1*reg68 - oz;
l1rx=tx*reg70+ty*reg73+tz*reg76;
l1ry=tx*reg71+ty*reg74+tz*reg77;
l1rz=tx*reg72+ty*reg75+tz*reg78;

tx1=l2x;ty1=l2y;tz1=l2z;
tx=tx1*reg60+ty1*reg63+tz1*reg66 - ox;
ty=tx1*reg61+ty1*reg64+tz1*reg67 - oy;
tz=tx1*reg62+ty1*reg65+tz1*reg68 - oz;
l2rx=tx*reg70+ty*reg73+tz*reg76;
l2ry=tx*reg71+ty*reg74+tz*reg77;
l2rz=tx*reg72+ty*reg75+tz*reg78;

tx1=l3x;ty1=l3y;tz1=l3z;
tx=tx1*reg60+ty1*reg63+tz1*reg66 - ox;
ty=tx1*reg61+ty1*reg64+tz1*reg67 - oy;
tz=tx1*reg62+ty1*reg65+tz1*reg68 - oz;
l3rx=tx*reg70+ty*reg73+tz*reg76;
l3ry=tx*reg71+ty*reg74+tz*reg77;
l3rz=tx*reg72+ty*reg75+tz*reg78;

tx1=l4x;ty1=l4y;tz1=l4z;
tx=tx1*reg60+ty1*reg63+tz1*reg66 - ox;
ty=tx1*reg61+ty1*reg64+tz1*reg67 - oy;
tz=tx1*reg62+ty1*reg65+tz1*reg68 - oz;
l4rx=tx*reg70+ty*reg73+tz*reg76;
l4ry=tx*reg71+ty*reg74+tz*reg77;
l4rz=tx*reg72+ty*reg75+tz*reg78;

tx1=l5x;ty1=l5y;tz1=l5z;
tx=tx1*reg60+ty1*reg63+tz1*reg66 - ox;
ty=tx1*reg61+ty1*reg64+tz1*reg67 - oy;
tz=tx1*reg62+ty1*reg65+tz1*reg68 - oz;
l5rx=tx*reg70+ty*reg73+tz*reg76;
l5ry=tx*reg71+ty*reg74+tz*reg77;
l5rz=tx*reg72+ty*reg75+tz*reg78;

// initialise counter
