code.perPoint:
/*
 triangle per triangle
*/

// load vertices and normal
xa=gmegabuf(c*12+4+offset);
ya=gmegabuf(c*12+5+offset);
za=gmegabuf(c*12+6+offset);
zsa=za;

xb=gmegabuf(c*12+7+offset);
yb=gmegabuf(c*12+8+offset);
zb=gmegabuf(c*12+9+offset);
zsb=zb;

xc=gmegabuf(c*12+10+offset);
yc=gmegabuf(c*12+11+offset);
zc=gmegabuf(c*12+12+offset);
zsc=zc;

nx1=gmegabuf(c*12+1+offset);
ny1=gmegabuf(c*12+2+offset);
nz1=gmegabuf(c*12+3+offset);

// rotate and transform all of them (dont shift normal)
tx1 = xa*mcxx + ya*mcyx + za*mczx -ox;
ty1 = xa*mcxy + ya*mcyy + za*mczy -oy;
tz1 = xa*mcxz + ya*mcyz + za*mczz -oz;
x1 = tx1*wcxx + ty1*wcyx + tz1*wczx;
y1 = tx1*wcxy + ty1*wcyy + tz1*wczy;
za = tx1*wcxz + ty1*wcyz + tz1*wczz;

tx2 = xb*mcxx + yb*mcyx + zb*mczx -ox;
ty2 = xb*mcxy + yb*mcyy + zb*mczy -oy;
tz2 = xb*mcxz + yb*mcyz + zb*mczz -oz;
x2 = tx2*wcxx + ty2*wcyx + tz2*wczx;
y2 = tx2*wcxy + ty2*wcyy + tz2*wczy;
zb = tx2*wcxz + ty2*wcyz + tz2*wczz;

tx3 = xc*mcxx + yc*mcyx + zc*mczx -ox;
ty3 = xc*mcxy + yc*mcyy + zc*mczy -oy;
tz3 = xc*mcxz + yc*mcyz + zc*mczz -oz;
x3 = tx3*wcxx + ty3*wcyx + tz3*wczx;
y3 = tx3*wcxy + ty3*wcyy + tz3*wczy;
zc = tx3*wcxz + ty3*wcyz + tz3*wczz;

tnx = nx1*mcxx + ny1*mcyx + nz1*mczx;
tny = nx1*mcxy + ny1*mcyy + nz1*mczy;
tnz = nx1*mcxz + ny1*mcyz + nz1*mczz;
nx = tnx*wcxx + tny*wcyx + tnz*wczx;
ny = tnx*wcxy + tny*wcyy + tnz*wczy;
nz = tnx*wcxz + tny*wcyz + tnz*wczz;

// work out center point for lighting/culling
cx=.333333*(x1+x2+x3);
cy=.333333*(y1+y2+y3);
cz=.333333*(za+zb+zc);

// work out eye vector
ex=-cx;
ey=-cy;
ez=-cz;

// normalise eye and normal
eo=invsqrt(sqr(ex)+sqr(ey)+sqr(ez));
enx=ex*eo;eny=ey*eo;enz=ez*eo;
no=invsqrt(sqr(nx)+sqr(ny)+sqr(nz));
nx=nx*no;ny=ny*no;nz=nz*no;

// work out culling (with some tolerance to hide rounding errors)
pld=x1*nx+y1*ny+za*nz;
nde=ex*nx+ey*ny+ez*nz;
skip=below(nde,pld);

// set depth value to render to z-buffer
z1=40000-1/eo;

// pre-opts for projection
skip=bor(skip,below(za,.01));
skip=bor(skip,below(zb,.01));
skip=bor(skip,below(zc,.01));
za=1/za;zb=1/zb;zc=1/zc;

