wczx=reg76;wczy=reg77;wczz=reg78;

// initialise counter
c=0;

code.perPoint:
/*
 texer per point
*/

x1=0;
y1=-2;
z1=132;

x2=0;
y2=-2;
z2=-132;


// rotate and transform
tx1 = x1*mcxx + y1*mcyx + z1*mczx -ox;
ty1 = x1*mcxy + y1*mcyy + z1*mczy -oy;
tz1 = x1*mcxz + y1*mcyz + z1*mczz -oz;
x1 = tx1*wcxx + ty1*wcyx + tz1*wczx;
y1 = tx1*wcxy + ty1*wcyy + tz1*wczy;
z1 = tx1*wcxz + ty1*wcyz + tz1*wczz;

tx2 = x2*mcxx + y2*mcyx + z2*mczx -ox;
ty2 = x2*mcxy + y2*mcyy + z2*mczy -oy;
tz2 = x2*mcxz + y2*mcyz + z2*mczz -oz;
x2 = tx2*wcxx + ty2*wcyx + tz2*wczx;
y2 = tx2*wcxy + ty2*wcyy + tz2*wczy;
z2 = tx2*wcxz + ty2*wcyz + tz2*wczz;

t=bnot(above(z1,z2));

x1=if(t,x1,x2);
y1=if(t,y1,y2);
z1=if(t,z1,z2);

red=if(t,1,0);
green=red;
blue=green;

skip=below(z1,.01);
z1=1/z1;

// projection
x=asp*x1*z1;y=y1*z1;

sizex=w*z1*.3;
sizey=sizex;
